/** the patch as the SysEx frame for a slot (0 = the first): F0 7D 53 59 31 01 lo hi <packed record> F7 */
export function frameFor(patch, slot) {
  const rec = new Uint8Array(PAYLOAD + 7);
  rec[0] = 0xa5;
  rec[1] = 1;
  rec[2] = rec[3] = 0xff;
  for (let i = 0; i < 23 && i < patch.name.length && patch.name[i]; i++)
    rec[4 + i] = patch.name[i] >= 32 && patch.name[i] < 127 ? patch.name[i] : 63;
  for (let i = 0; i < NPARAMS; i++) {
    rec[28 + 2 * i] = patch.values[i] & 0xff;
    rec[29 + 2 * i] = (patch.values[i] >> 8) & 0xff;
  }
  const out = [0xf0, 0x7d, 0x53, 0x59, 0x31, 0x01, slot & 0x7f, (slot >> 7) & 0x7f];
  for (let i = 0; i < PAYLOAD; i += 7) {
    let top = 0;
    for (let j = 0; j < 7; j++) top |= (rec[i + j] >> 7) << j;
    out.push(top);
    for (let j = 0; j < 7; j++) out.push(rec[i + j] & 0x7f);
  }
  out.push(0xf7);
  return Uint8Array.from(out);
}

export function nameText(patch) {
  let t = "";
  for (let i = 0; i < 23 && i < patch.name.length && patch.name[i]; i++)
    t += patch.name[i] >= 32 && patch.name[i] < 127 ? String.fromCharCode(patch.name[i]) : "?";
  return t;
}

