/** Read ZIP entries in memory. Only stored/deflated ZIPs; bounded to protect local imports. */
export async function unzipEntries(buf, budget = { bytes: 0, entries: 0 }) {
  const b = new Uint8Array(buf), dv = new DataView(b.buffer, b.byteOffset, b.byteLength), out = [];
  const MAX_BYTES = 64 * 1024 * 1024, MAX_ENTRIES = 30000;
  let eocd = -1;
  for (let i = b.length - 22; i >= 0 && i >= b.length - 65557; i--)
    if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
  if (eocd < 0) throw new Error("Not a ZIP archive.");
  const count = dv.getUint16(eocd + 10, true);
  if (budget.entries + count > MAX_ENTRIES) throw new Error("This archive contains too many entries.");
  budget.entries += count;
  let at = dv.getUint32(eocd + 16, true);
  for (let k = 0; k < count; k++) {
    if (at + 46 > b.length || dv.getUint32(at, true) !== 0x02014b50) throw new Error("Damaged ZIP directory.");
    const flags = dv.getUint16(at + 8, true), method = dv.getUint16(at + 10, true);
    const csize = dv.getUint32(at + 20, true), size = dv.getUint32(at + 24, true);
    const nlen = dv.getUint16(at + 28, true), xlen = dv.getUint16(at + 30, true), clen = dv.getUint16(at + 32, true);
    const local = dv.getUint32(at + 42, true);
    if (at + 46 + nlen + xlen + clen > b.length) throw new Error("Damaged ZIP entry.");
    const name = new TextDecoder(flags & 0x800 ? "utf-8" : "windows-1252").decode(b.subarray(at + 46, at + 46 + nlen));
    at += 46 + nlen + xlen + clen;
    if (name.endsWith("/") || /(^|\/)\._|(^|\/)__MACOSX\//.test(name)) continue;
    if (flags & 1) throw new Error("Password-protected ZIPs are not supported.");
    if (size + budget.bytes > MAX_BYTES) throw new Error("The expanded collection is too large (64 MB maximum).");
    if (local + 30 > b.length || dv.getUint32(local, true) !== 0x04034b50) throw new Error("Damaged ZIP header.");
    const start = local + 30 + dv.getUint16(local + 26, true) + dv.getUint16(local + 28, true);
    if (start + csize > b.length) throw new Error("Truncated ZIP data.");
    const raw = b.subarray(start, start + csize);
    let bytes;
    if (method === 0) bytes = raw.slice();
    else if (method === 8) {
      const reader = new Blob([raw]).stream().pipeThrough(new DecompressionStream("deflate-raw")).getReader();
      const chunks = []; let length = 0;
      for (;;) {
        const {value, done} = await reader.read(); if (done) break;
        length += value.length;
        if (budget.bytes + length > MAX_BYTES || length > size) { await reader.cancel(); throw new Error("ZIP expansion exceeds its limit."); }
        chunks.push(value);
      }
      bytes = new Uint8Array(length); let offset = 0;
      for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length; }
    } else throw new Error("This ZIP uses an unsupported compression method.");
    if (bytes.length !== size) throw new Error("ZIP entry length does not match.");
    budget.bytes += bytes.length;
    out.push({name, bytes});
  }
  return out.sort((x,y)=>x.name.localeCompare(y.name, undefined, {numeric:true}));
}

/** Patches in a ZIP or a collection of nested bank ZIPs; the path preserves bank provenance. */
export async function unzipSy1(buf, depth = 0, budget = {bytes:0, entries:0}) {
  if (depth > 4) throw new Error("ZIP nesting is too deep.");
  const out = [];
  for (const entry of await unzipEntries(buf, budget)) {
    if (/\.sy1$/i.test(entry.name)) out.push(entry);
    else if (/\.zip$/i.test(entry.name)) {
      for (const patch of await unzipSy1(entry.bytes, depth+1, budget))
        out.push({name:entry.name+"/"+patch.name, bytes:patch.bytes});
    }
  }
  return out;
}

// ------------------------------------------------------------------ the page
let midi = null, waiting = null, busy = false;
const ui = {};

function fromDevice(msg) {                 // the FM-1's answers: F0 7D 53 59 31 <cmd> ...
  if (msg.length < 7 || msg[1] !== 0x7d || msg[2] !== 0x53 || msg[3] !== 0x59 || msg[4] !== 0x31) return;
  if (waiting && waiting.cmd === msg[5]) {
    const w = waiting;
    waiting = null;
    clearTimeout(w.timer);
    w.done(msg);
  }
}
function ask(frame, cmd, ms = 3000) {      // a frame out, its answer back (null: none came)
  return new Promise((done) => {
    waiting = { cmd, done, timer: setTimeout(() => { waiting = null; done(null); }, ms) };
    midi.toDevice(frame);
  });
}
const say = (t) => { ui.status.textContent = t; };

async function used() {                    // the slots in use on the FM-1 (up to the last one), or null
  const a = await ask([0xf0, 0x7d, 0x53, 0x59, 0x31, 0x03, 0xf7], 0x43, 1500);
  return a ? a[6] | a[7] << 7 : null;
}

async function load(files) {
  if (busy || !midi) return;
  busy = true;
  try {
    const patches = [];
    let skipped = 0;
    for (const f of [...files].sort((x, y) => x.name.localeCompare(y.name, undefined, { numeric: true }))) {
      const buf = await f.arrayBuffer();
      const parts = /\.zip$/i.test(f.name) ? await unzipSy1(buf).catch(() => []) : [{ name: f.name, bytes: new Uint8Array(buf) }];
      if (!parts.length) skipped++;
      for (const part of parts) {
        const p = parseSy1(part.bytes);
        if (p.lines) patches.push(p);
        else skipped++;
      }
    }
    if (!patches.length) { say("No Synth1 patches in what you dropped (.sy1 files, or a .zip of them)."); return; }
    let slot = clamp((parseInt(ui.first.value, 10) || 1) - 1, 0, SLOTS - 1), stored = 0, failed = 0;
    const from = slot + 1, rows = [];
    for (const p of patches) {
      if (slot >= SLOTS) { failed += patches.length - stored - failed; break; }
      say(`Sending ${stored + failed + 1} of ${patches.length}: ${nameText(p)}`);
      const a = await ask(frameFor(p, slot), 0x41);
      if (a && a[8] === 0) {
        rows.push(`${String(slot + 1).padStart(3, "0")}  ${nameText(p)}`);
        stored++;
        slot++;
      } else failed++;
    }
    ui.list.textContent = rows.join("\n");
    ui.list.hidden = !rows.length;
    ui.first.value = String(Math.min(slot + 1, SLOTS));
    say(`${stored} patch${stored === 1 ? "" : "es"} stored in ${String(from).padStart(3, "0")}`
      + (stored > 1 ? `–${String(slot).padStart(3, "0")}` : "")
      + (failed ? `; ${failed} not stored (no answer from the FM-1, or the bank is full)` : "")
      + (skipped ? `; ${skipped} file${skipped === 1 ? "" : "s"} skipped (not a patch)` : "")
      + ". Turn PRESETS past the built-in ones to play them.");
  } finally {
    busy = false;
  }
}

async function eraseAll() {
  if (busy || !midi) return;
  if (!confirm("Erase every patch you loaded into this FM-1? The built-in ones stay.")) return;
  busy = true;
  const a = await ask([0xf0, 0x7d, 0x53, 0x59, 0x31, 0x02, 0xf7], 0x42, 8000);
  busy = false;
  ui.list.hidden = true;
  ui.first.value = "1";
  say(a && a[6] === 0 ? "All loaded patches erased." : "The FM-1 did not answer the erase.");
}

// A patch from the Patch Manager's page (this one in its hidden frame): into slot 1 of the browser's own emulated
// flash, selected, then a short phrase. One at a time; a newer one cuts the phrase of the one before.
let auditions = Promise.resolve(), phrase = 0;
async function audition(name, bytes) {
  const patch = parseSy1(bytes), run = ++phrase;
  if (!patch.lines) throw new Error("Invalid preview patch.");
  const answer = await ask(frameFor(patch, 0), 0x41);
  if (!answer || answer[8] !== 0) throw new Error("The browser synth did not confirm the preview.");
  midi.toDevice([0xc0, 8]);
  say(`Preview: ${name}.`);
  (async () => {
    for (const note of [48, 55, 60, 64]) {
      if (run !== phrase) return;
      midi.toDevice([0x90, note, 92]);
      await new Promise((r) => setTimeout(r, 350));
      midi.toDevice([0x80, note, 0]);
    }
  })();
}

function el(tag, attrs = {}, text = "") {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
  if (text) e.textContent = text;
  return e;
}

export async function attach(ctx) {
  try {
    midi = await import("./parts/midi.js");
  } catch {
    ctx.status("The patch loader needs the emulator's MIDI part (fm1.toml emu = [\"midi\"]).");
    return;
  }
  midi.fromDevice(fromDevice);
  const style = el("style");
  style.textContent = `
    .sy1 { margin: 1rem 0 0; padding: 14px 16px; background: var(--card); border: 1px solid var(--rule); border-radius: 12px; }
    .sy1 h2 { font-size: 1rem; margin: 0 0 .5rem; }
    .sy1 .drop { border: 2px dashed var(--muted); border-radius: 10px; padding: 18px 14px; text-align: center; color: var(--muted); }
    .sy1 .drop.over { border-color: var(--accent); color: var(--ink); }
    .sy1 .row { display: flex; flex-wrap: wrap; gap: .5rem 1rem; align-items: center; margin-top: .7rem; font-size: .92rem; color: var(--muted); }
    .sy1 button, .sy1 input[type=number] { font: inherit; color: var(--ink); background: var(--card); border: 1px solid var(--muted); border-radius: 8px; padding: .3em .8em; min-height: 2.2em; }
    .sy1 button { cursor: pointer; }
    .sy1 input[type=number] { width: 5.5em; }
    .sy1 pre { margin: .7rem 0 0; max-height: 14em; overflow: auto; font-size: .85rem; color: var(--ink); }
    .sy1 [role=status] { margin: .7rem 0 0; min-height: 1.3em; font-size: .92rem; }`;
  document.head.append(style);
  const box = el("section", { class: "sy1", "aria-label": "Synth1 patches" });
  const drop = el("div", { class: "drop" }, "Drop Synth1 patches here: .sy1 files, or a .zip bank");
  const row = el("div", { class: "row" });
  const pick = el("button", { type: "button" }, "Choose files");
  const input = el("input", { type: "file", multiple: "", accept: ".sy1,.zip", hidden: "" });
  const label = el("label", {}, "First slot ");
  ui.first = el("input", { type: "number", min: "1", max: String(SLOTS), value: "1" });
  label.append(ui.first);
  const erase = el("button", { type: "button" }, "Erase loaded patches");
  ui.status = el("p", { role: "status" });
  ui.list = el("pre", { hidden: "" });
  row.append(pick, input, label, erase);
  box.append(el("h2", {}, "Synth1 patches"), drop, row, ui.status, ui.list);
  const bar = document.querySelector(".bar");
  (bar ? bar.parentNode : document.body).insertBefore(box, bar ? bar.nextSibling : null);

  pick.addEventListener("click", () => input.click());
  input.addEventListener("change", () => { load(input.files); input.value = ""; });
  erase.addEventListener("click", eraseAll);
  const stop = (e) => { e.preventDefault(); e.stopPropagation(); };
  for (const t of [drop, document.body]) {
    t.addEventListener("dragover", (e) => { stop(e); drop.classList.add("over"); });
    t.addEventListener("dragleave", (e) => { stop(e); drop.classList.remove("over"); });
    t.addEventListener("drop", (e) => { stop(e); drop.classList.remove("over"); load(e.dataTransfer.files); });
  }
  // Wait for the user's Switch on gesture and the worklet before sending SysEx.
  const initialized = async () => {
    if (!document.getElementById("start")?.hidden) { setTimeout(initialized, 100); return; }
    const n = await used();
    if (n !== null) {
      ui.first.value = String(Math.min(n + 1, SLOTS));
      if (n) say(`${n} slot${n === 1 ? "" : "s"} in use on this FM-1.`);
    }
    if (window.parent !== window) {      // inside the Patch Manager: it sends the patches to audition
      window.addEventListener("message", (e) => {
        if (e.origin !== location.origin || e.source !== window.parent || !e.data || e.data.sy1 !== "preview") return;
        const { id, name, bytes } = e.data;
        auditions = auditions.then(() => audition(name, bytes))
          .then(() => ({ ok: true }), (error) => ({ ok: false, error: error.message }))
          .then((answer) => window.parent.postMessage({ sy1: "previewed", id, ...answer }, location.origin));
      });
      window.parent.postMessage({ sy1: "ready" }, location.origin);
    }
    const key = new URLSearchParams(location.search).get("preview");
    if (!key || !/^sy1-preview-[a-f0-9-]+$/.test(key)) return;
    try {
      const preview = JSON.parse(localStorage.getItem(key) || "null");
      localStorage.removeItem(key);
      if (!preview || Date.now() - preview.created > 3600000) throw new Error("Preview expired; choose it again in the Patch Manager.");
      const bytes = Uint8Array.from(atob(preview.bytes), c => c.charCodeAt(0));
      const patch = parseSy1(bytes);
      if (!patch.lines) throw new Error("Invalid preview patch.");
      // Slot 1 is in the browser's separate emulated flash, never the USB hardware.
      const answer = await ask(frameFor(patch, 0), 0x41);
      if (!answer || answer[8] !== 0) throw new Error("The browser synth did not confirm the preview.");
      midi.toDevice([0xc0, 8]);
      say(`Preview: ${preview.name}. Play the keyboard below, or try a phrase.`);
      const phrase = el("button", {type:"button"}, "Play preview phrase");
      phrase.addEventListener("click", async () => {
        phrase.disabled = true;
        try {
          for (const note of [48, 55, 60, 64]) {
            midi.toDevice([0x90, note, 92]);
            await new Promise(r => setTimeout(r, 350));
            midi.toDevice([0x80, note, 0]);
          }
        } finally { phrase.disabled = false; }
      });
      row.append(phrase);
    } catch (error) { say(error.message); }
  };
  initialized();
}
